/* @autogenerated */
import { Location } from '@angular/common';
import { provideLocationMocks } from '@angular/common/testing';
import { Component, inject, OnInit } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { Params, provideRouter, Router } from '@angular/router';
import { RouterTestingHarness } from '@angular/router/testing';
import { LocalRouteStateService } from './local-route-state.service';

@Component({
  template: `<p>{{ view }}</p>`,
  providers: [LocalRouteStateService],
})
class StatefulPageComponent implements OnInit {
  readonly state = inject(LocalRouteStateService);
  readonly bind = this.state.bind(['view']);
  view?: string;
  received: Params[] = [];

  ngOnInit(): void {
    this.bind.watch().subscribe((params) => {
      this.received.push(params);
      this.view = params['view'];
    });
  }
}

@Component({ template: `<p>other</p>` })
class OtherPageComponent {}

// El popstate de location.back() se procesa en una tarea posterior
const settle = () => new Promise((resolve) => setTimeout(resolve));

describe('LocalRouteStateService', () => {
  let harness: RouterTestingHarness;
  let router: Router;

  beforeEach(async () => {
    TestBed.configureTestingModule({
      providers: [
        provideLocationMocks(),
        provideRouter([
          { path: 'list', component: StatefulPageComponent },
          { path: 'other', component: OtherPageComponent },
        ]),
      ],
    });
    harness = await RouterTestingHarness.create();
    router = TestBed.inject(Router);
  });

  it('merges inner and outer query params on go', async () => {
    const page = await harness.navigateByUrl('/list?view=a&other=1', StatefulPageComponent);

    page.bind.go({ view: 'b', ignored: 'x' });
    await harness.fixture.whenStable();

    expect(router.url).toBe('/list?other=1&view=b');
  });

  it('emits synchronously and only when bound params change', async () => {
    const page = await harness.navigateByUrl('/list?view=a&other=1', StatefulPageComponent);
    expect(page.received).toEqual([{ view: 'a' }]);

    await harness.navigateByUrl('/list?view=a&other=2');
    await harness.navigateByUrl('/list?view=b&other=2');

    expect(page.received).toEqual([{ view: 'a' }, { view: 'b' }]);
  });

  it('does not navigate when destroyed by a navigation (detail → other menu entry)', async () => {
    await harness.navigateByUrl('/list?view=detail&other=1', StatefulPageComponent);
    const navigate = spyOn(router, 'navigate').and.callThrough();

    await harness.navigateByUrl('/other?menu=1');
    await harness.fixture.whenStable();

    expect(navigate).not.toHaveBeenCalled();
    expect(router.url).toBe('/other?menu=1');
  });

  it('keeps back navigation predictable after leaving the screen', async () => {
    const location = TestBed.inject(Location);
    // En TestBed no hay bootstrap: hay que activar a mano la escucha de popstate
    router.initialNavigation();
    await harness.navigateByUrl('/list');
    await harness.navigateByUrl('/list?view=detail');
    await harness.navigateByUrl('/other');

    location.back();
    await settle();
    expect(router.url).toBe('/list?view=detail');

    location.back();
    await settle();
    expect(router.url).toBe('/list');
  });

  it('clears its params replacing the url when destroyed outside a navigation', async () => {
    await harness.navigateByUrl('/list?view=detail&other=1', StatefulPageComponent);
    const navigate = spyOn(router, 'navigate').and.callThrough();

    harness.fixture.destroy();

    expect(navigate).toHaveBeenCalledOnceWith([], {
      queryParams: { other: '1' },
      queryParamsHandling: 'replace',
      replaceUrl: true,
    });
  });

  it('does not navigate on destroy when its params are not in the url', async () => {
    await harness.navigateByUrl('/list?other=1', StatefulPageComponent);
    const navigate = spyOn(router, 'navigate').and.callThrough();

    harness.fixture.destroy();

    expect(navigate).not.toHaveBeenCalled();
  });
});
